#!/usr/bin/env node
'use strict';

// Claude Code after-tool (PostToolUse) hook for GitHub writes: when what GitHub sent back ends with the
// "Generated by Claude Code" footer the cloud route appends, it tells the agent to remove it straight
// away (see toolkit-github-footer-guard.cjs). It never blocks the write itself, which has already
// happened: unreadable input or a failing check exits 0 with nothing printed.
const fs = require('node:fs');

function main(deps = {}) {
  try {
    const raw = deps.stdin !== undefined ? deps.stdin : fs.readFileSync(0, 'utf8');
    const input = JSON.parse(raw || '{}');
    const guard = deps.guard || require('./toolkit-github-footer-guard.cjs');
    const decision = guard.footerDecision(input, deps);
    if (decision && Object.keys(decision).length) (deps.write || ((text) => process.stdout.write(text)))(`${JSON.stringify(decision)}\n`);
  } catch {
    // Nothing to check against, and a GitHub write must never fail because of this hook.
  }
  return 0;
}

if (require.main === module) process.exitCode = main();

module.exports = { main };
